Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
function Get-InstallMedia {
    # Use .NET DriveInfo to correctly identify Fixed/Removable drives and avoid network/floppy hangs
    $drives = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -in 'Fixed', 'Removable' -and $_.IsReady }
    foreach ($drive in $drives) {
        $path = Join-Path -Path $drive.RootDirectory.FullName -ChildPath "drivers"
        if (Test-Path -Path $path -PathType Container) {
            return $drive.RootDirectory.FullName
        }
    }
    return $null
}

function Get-InstallerFile {
    param([string]$Path, [string[]]$Extensions = @("*.exe"))
    if (Test-Path -Path $Path) {
        foreach ($ext in $Extensions) {
            $file = Get-ChildItem -Path $Path -Filter $ext | Select-Object -First 1
            if ($file) { return $file.FullName }
        }
    }
    return $null
}

function Write-SetupLog {
    param(
        [string]$Message,
        [string]$Path = "$env:SystemRoot\Panther\Autounattend_Log.txt"
    )
    # Ensure directory exists
    $dir = Split-Path -Path $Path -Parent
    if (-not (Test-Path -Path $dir)) {
        New-Item -Path $dir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
    }

    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss.fff"
    $logEntry = "[$timestamp] $Message"
    Add-Content -Path $Path -Value $logEntry -ErrorAction SilentlyContinue
}

function Get-RemoteFile {
    param(
        [string]$Url,
        [string]$Destination,
        [string]$Name = "File"
    )

    # Suppress Progress Bar for Faster Download
    $ProgressPreference = 'SilentlyContinue'

    if ([string]::IsNullOrWhiteSpace($Url)) { return $false }

    Write-SetupLog "Attempting to download $Name from $Url..."

    # Increase timeout to ~5 minutes (150 * 2s) to handle slow network initialization
    $maxRetries = 150
    $retry = 0
    $connected = $false

    # Wait for network
    while (-not $connected -and $retry -lt $maxRetries) {
        $testHosts = @("google.com", "microsoft.com", "cloudflare.com")
        foreach ($hostName in $testHosts) {
            try {
                $null = [System.Net.Dns]::GetHostEntry($hostName)
                $connected = $true
                break
            } catch {}
        }

        if (-not $connected) {
            $retry++
            Start-Sleep -Seconds 2
        }
    }

    if (-not $connected) {
        Write-SetupLog "No network connectivity to download $Name."
        return $false
    }

    $downloadRetries = 5
    $dRetry = 0
    $downloaded = $false

    while (-not $downloaded -and $dRetry -lt $downloadRetries) {
        try {
            # Enable TLS 1.2 and TLS 1.3 (if available)
            $protocols = [Net.SecurityProtocolType]::Tls12
            try { $protocols = $protocols -bor [Net.SecurityProtocolType]::Tls13 } catch {}
            [Net.ServicePointManager]::SecurityProtocol = $protocols

            Invoke-WebRequest -Uri $Url -OutFile $Destination -UseBasicParsing -ErrorAction Stop

            # Verify file size > 1KB (1024 bytes) to ensure valid download
            if (Test-Path -Path $Destination -And (Get-Item $Destination).Length -gt 1024) {
                Write-SetupLog "Download of $Name successful."
                $downloaded = $true
            } else {
                Write-SetupLog "Download of $Name failed (file too small or empty)."
                throw "File too small"
            }
        } catch {
            $dRetry++
            Write-SetupLog "Failed to download $Name (Attempt $dRetry/$downloadRetries): $_"
            Start-Sleep -Seconds 5
        }
    }

    return $downloaded
}


function Set-RegistryKey {
    param (
        [Parameter(Mandatory=$true)]
        [string]$Path,
        [Parameter(Mandatory=$true)]
        [string]$Name,
        [Parameter(Mandatory=$true)]
        [string]$Value,
        [string]$Type = "String"
    )

    # Handle root mapping accurately based on memory
    $fullPath = $Path -replace '^HKLM\\', 'HKLM:\' `
                      -replace '^HKCU\\', 'HKCU:\' `
                      -replace '^HKU\\', 'Registry::HKEY_USERS\' `
                      -replace '^HKEY_USERS\\', 'Registry::HKEY_USERS\'

    $splitPath = $fullPath -split "\\"
    $parentPath = $splitPath[0]

    if (-not ($parentPath.EndsWith(":") -or $parentPath.StartsWith("Registry::"))) {
        Write-SetupLog "Invalid registry root for path: $Path"
        return
    }

    # Iteratively create intermediate keys
    for ($i = 1; $i -lt $splitPath.Count; $i++) {
        $parentPath = Join-Path -Path $parentPath -ChildPath $splitPath[$i]
        if (-not (Test-Path -LiteralPath $parentPath)) {
            try {
                New-Item -Path ($parentPath -replace "\\[^\\]+$", "") -Name $splitPath[$i] -Force -ErrorAction Stop | Out-Null
            } catch {
                Write-SetupLog "Failed to create registry key: $parentPath - $_"
                return
            }
        }
    }

    # Set value
    try {
        if ($Name -eq "") {
            Set-Item -LiteralPath $fullPath -Value $Value -Force -ErrorAction Stop
        } else {
            Set-ItemProperty -LiteralPath $fullPath -Name $Name -Value $Value -Type $Type -Force -ErrorAction Stop
        }
    } catch {
        Write-SetupLog "Failed to set registry value $Name at $fullPath - $_"
    }
}

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-SetupLog "Starting Network Driver Installation..."
$mediaRoot = Get-InstallMedia

if ($mediaRoot) {
    $driverPath = Join-Path -Path $mediaRoot -ChildPath "drivers\network"
    if (Test-Path -Path $driverPath) {
        Write-SetupLog "Found network drivers path at $driverPath"
        # Check if there are any INF files to avoid pnputil error
        if (Get-ChildItem -Path $driverPath -Filter "*.inf" -Recurse) {
            try {
                $pnputilArgs = @("/add-driver", "$driverPath\*.inf", "/subdirs", "/install")
                # Redirect standard output and error to logs for debugging
                Start-Process -FilePath "pnputil.exe" -ArgumentList $pnputilArgs -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\pnputil_network.log" -RedirectStandardError "$env:TEMP\pnputil_network_err.log"
                Write-SetupLog "Network driver installation completed."
            }
            catch {
                Write-SetupLog "Error installing network drivers: $_"
            }
        } else {
            Write-SetupLog "No INF files found in $driverPath"
        }
    } else {
        Write-SetupLog "No network drivers folder found at $driverPath"
    }
} else {
    Write-SetupLog "Install media not found."
}

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

# OPTIONAL: Set a direct download URL for the Nvidia Driver here.
$DownloadUrl = ""

Write-SetupLog "Starting Nvidia Driver Installation..."
$mediaRoot = Get-InstallMedia
$setupPath = $null

# Try Local (Primary)
if ($mediaRoot) {
    Write-SetupLog "Checking local storage..."
    $driverDir = Join-Path -Path $mediaRoot -ChildPath "drivers\nvidia"
    $setupPath = Get-InstallerFile -Path $driverDir
}

# Try Download (Fallback if URL provided)
if (-not $setupPath -and $DownloadUrl) {
    $dest = "$env:TEMP\nvidia_driver.exe"
    if (Get-RemoteFile -Url $DownloadUrl -Destination $dest -Name "Nvidia Driver") {
        $setupPath = $dest
    }
}

if ($setupPath) {
    Write-SetupLog "Installing Nvidia driver from $setupPath..."
    try {
        Unblock-File -Path $setupPath -ErrorAction SilentlyContinue
        # -s: Silent, -n: No splash, -f: Force, -noreboot: No reboot
        Start-Process -FilePath $setupPath -ArgumentList @('-s', '-n', '-f', '-noreboot') -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\nvidia_install.log"
        Write-SetupLog "Nvidia driver installation completed."
    }
    catch {
        Write-SetupLog "Error installing Nvidia drivers: $_"
    }
} else {
    Write-SetupLog "Nvidia installer not found locally."
}

