Write-SetupLog "Starting Visual C++ Runtimes Installation..."

$mediaRoot = Get-InstallMedia

function Install-Runtime {
    param(
        [string]$Url,
        [string]$DestName,
        [string]$LogName,
        [string]$LocalFolder
    )

    $setupPath = $null
    $dest = "$env:TEMP\$DestName"

    # 1. Try Download (Online First)
    if (Get-RemoteFile -Url $Url -Destination $dest -Name $LogName) {
        $setupPath = $dest
    }

    # 2. Try Local (Fallback)
    if (-not $setupPath -and $mediaRoot) {
        Write-SetupLog "Download of $LogName failed. Checking local storage..."
        $possiblePaths = @(
            (Join-Path $mediaRoot "apps\$LocalFolder"),
            (Join-Path $mediaRoot "drivers\apps\$LocalFolder"),
            (Join-Path $mediaRoot "Apps\$LocalFolder"),
            (Join-Path $mediaRoot "Drivers\Apps\$LocalFolder")
        )
        foreach ($path in $possiblePaths) {
             if (Test-Path $path) {
                 $localInstaller = Get-InstallerFile -Path $path
                 if ($localInstaller) {
                    $setupPath = $localInstaller
                    break
                 }
             }
        }
    }

    if ($setupPath) {
        Write-SetupLog "Installing $LogName from $setupPath..."
        try {
            Unblock-File -Path $setupPath -ErrorAction SilentlyContinue
            Start-Process -FilePath $setupPath -ArgumentList @("/install", "/quiet", "/norestart") -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\${DestName}_install.log"
            Write-SetupLog "$LogName installation completed."
        } catch {
            Write-SetupLog "Error installing $($LogName): $_"
        }
    } else {
        Write-SetupLog "$LogName installer not found locally and download failed."
    }
}

# Official Microsoft Link for Latest Supported VC++ 2015-2022
$url64 = "https://aka.ms/vc14/vc_redist.x64.exe"
$url86 = "https://aka.ms/vc14/vc_redist.x86.exe"

Install-Runtime -Url $url64 -DestName "vc_redist.x64.exe" -LogName "Visual C++ Runtimes (x64)" -LocalFolder "vcredist_x64"
Install-Runtime -Url $url86 -DestName "vc_redist.x86.exe" -LogName "Visual C++ Runtimes (x86)" -LocalFolder "vcredist_x86"

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-SetupLog "Starting Chrome Installation..."

# Check if Chrome is already installed
if ((Test-Path "$env:ProgramFiles\Google\Chrome\Application\chrome.exe") -or (Test-Path "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe")) {
    Write-SetupLog "Chrome is already installed. Skipping."
    return
}

$mediaRoot = Get-InstallMedia
$setupPath = $null

# 1. Try Download (Online First) - Prefer Enterprise MSI
$url = 'https://dl.google.com/chrome/install/googlechromestandaloneenterprise64.msi'
$dest = "$env:TEMP\chrome.msi"
if (Get-RemoteFile -Url $url -Destination $dest -Name "Chrome Enterprise MSI") {
    $setupPath = $dest
}

# 2. Try Local (Fallback)
if (-not $setupPath -and $mediaRoot) {
    Write-SetupLog "Download failed. Checking local storage..."
    $possiblePaths = @(
        (Join-Path $mediaRoot "apps\chrome"),
        (Join-Path $mediaRoot "drivers\apps\chrome"),
        (Join-Path $mediaRoot "Apps"),
        (Join-Path $mediaRoot "Drivers\Apps")
    )
    foreach ($path in $possiblePaths) {
         if (Test-Path $path) {
             # Prioritize MSI, then EXE
             $localInstaller = Get-InstallerFile -Path $path -Extensions @("*.msi", "*.exe")
             if ($localInstaller) {
                $setupPath = $localInstaller
                break
             }
         }
    }
}

if ($setupPath) {
    Write-SetupLog "Installing Chrome from $setupPath..."
    try {
        Unblock-File -Path $setupPath -ErrorAction SilentlyContinue

        if ($setupPath -match '\.msi$') {
            # MSI Installation
            # Note: msiexec requires strict quoting for paths with spaces
            $msiArgs = @("/i", "$setupPath", "/qn", "/norestart")
            Start-Process -FilePath "msiexec.exe" -ArgumentList $msiArgs -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\chrome_install.log"
        } else {
            # EXE Installation
            Start-Process -FilePath $setupPath -ArgumentList @('/silent', '/install') -Wait -NoNewWindow -RedirectStandardOutput "$env:TEMP\chrome_install.log"
        }

        # Cleanup temp file
        if ($setupPath -match "$env:TEMP\\chrome\.(msi|exe)") {
            Remove-Item -Path $setupPath -Force -ErrorAction SilentlyContinue
        }
        Write-SetupLog "Chrome installation completed."
    } catch {
        Write-SetupLog "Error installing Chrome: $_"
    }
} else {
    Write-SetupLog "Chrome installer not found locally and download failed."
}

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

$packagesToRemove = @(
    'Microsoft.Microsoft3DViewer',
    'Microsoft.BingSearch',
    'Microsoft.WindowsCamera',
    'Clipchamp.Clipchamp',
    'Microsoft.WindowsAlarms',
    'Microsoft.549981C3F5F10', # Cortana
    'Microsoft.Copilot',
    'Microsoft.Windows.DevHome',
    'MicrosoftCorporationII.MicrosoftFamily',
    'Microsoft.WindowsFeedbackHub',
    'Microsoft.GetHelp',
    'Microsoft.Getstarted',
    'microsoft.windowscommunicationsapps',
    'Microsoft.WindowsMaps',
    'Microsoft.MixedReality.Portal',
    'Microsoft.BingNews',
    'Microsoft.MicrosoftOfficeHub',
    'Microsoft.Office.OneNote',
    'Microsoft.OutlookForWindows',
    'Microsoft.People',
    'Microsoft.Windows.PeopleExperienceHost',
    'Microsoft.Windows.Photos',
    'Microsoft.PowerAutomateDesktop',
    'MicrosoftCorporationII.QuickAssist',
    'Microsoft.SkypeApp',
    'Microsoft.MicrosoftSolitaireCollection',
    'Microsoft.MicrosoftStickyNotes',
    'MicrosoftTeams',
    'MSTeams',
    'Microsoft.Todos',
    'Microsoft.WindowsSoundRecorder',
    'Microsoft.Wallet',
    'Microsoft.BingWeather',
    'Microsoft.ZuneVideo',
    'MicrosoftWindows.Client.WebExperience',
    'Microsoft.Windows.Ai.Copilot.Provider',
    'Microsoft.YourPhone',
    'Microsoft.GamingApp',
    'Microsoft.XboxGameOverlay',
    'Microsoft.XboxGamingOverlay',
    'Microsoft.XboxIdentityProvider',
    'Microsoft.XboxSpeechToTextOverlay',
    'Microsoft.Windows.ParentalControls'
)

$packagesToKeep = @(
    'Microsoft.MSPaint',
    'Microsoft.WindowsNotepad'
)

$capabilitiesToRemove = @(
    'Print.Fax.Scan',
    'Browser.InternetExplorer',
    'MathRecognizer',
    'OneCoreUAP.OneSync',
    'App.Support.QuickAssist',
    'App.StepsRecorder',
    'Hello.Face',
    'Media.WindowsMediaPlayer',
    'Microsoft.Windows.WordPad'
)

$featuresToRemove = @(
    'MediaPlayback',
    'Microsoft-RemoteDesktopConnection',
    'Recall'
)

Write-SetupLog "Starting Debloating Process..."

# Remove Appx Provisioned Packages
$provisioned = Get-AppxProvisionedPackage -Online
foreach ($package in $packagesToRemove) {
    $found = $provisioned | Where-Object { $_.DisplayName -eq $package -or $_.PackageName -like "*$package*" }
    if ($found) {
        foreach ($item in $found) {
            if ($packagesToKeep -contains $item.DisplayName) {
                Write-SetupLog "Skipping preserved package $($item.DisplayName)..."
                continue
            }
            Write-SetupLog "Removing $($item.DisplayName) ($($item.PackageName))..."
            try {
                Remove-AppxProvisionedPackage -Online -PackageName $item.PackageName -ErrorAction Continue | Out-Null
            } catch {
                Write-SetupLog "Failed to remove $($item.PackageName): $_"
            }
        }
    }
}

# Remove Capabilities
$capabilities = Get-WindowsCapability -Online
foreach ($capName in $capabilitiesToRemove) {
    $cap = $capabilities | Where-Object { ($_.Name -split '~')[0] -eq $capName -and $_.State -ne 'NotPresent' }
    if ($cap) {
        Write-SetupLog "Removing capability $capName..."
        try {
            Remove-WindowsCapability -Online -Name $cap.Name -ErrorAction Continue | Out-Null
        } catch {
            Write-SetupLog "Failed to remove capability $($capName): $_"
        }
    }
}

# Remove Optional Features
foreach ($feature in $featuresToRemove) {
    if ((Get-WindowsOptionalFeature -Online -FeatureName $feature -ErrorAction SilentlyContinue).State -eq 'Enabled') {
        Write-SetupLog "Disabling feature $feature..."
        try {
            Disable-WindowsOptionalFeature -Online -FeatureName $feature -Remove -NoRestart -ErrorAction Continue | Out-Null
        } catch {
            Write-SetupLog "Failed to disable feature $($feature): $_"
        }
    }
}

Write-SetupLog "Debloating Process Completed."

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-SetupLog "Applying System Optimizations..."

# 1. Disable Hibernation (Saves disk space)
try {
    powercfg -h off
    Write-SetupLog "Hibernation disabled."
} catch {
    Write-SetupLog "Failed to disable hibernation: $_"
}

# 2. Set High Performance Power Plan
try {
    powercfg -setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c
    Write-SetupLog "Power plan set to High Performance."
} catch {
    Write-SetupLog "Failed to set power plan: $_"
}

# 3. Disable Game DVR (Background recording)
Set-RegistryKey -Path "HKLM\SOFTWARE\Policies\Microsoft\Windows\GameDVR" -Name "AllowGameDVR" -Value 0 -Type DWord

# 4. Disable Last Access Timestamp (Reduces disk I/O)
try {
    fsutil behavior set disablelastaccess 1
    Write-SetupLog "Last Access Timestamp disabled."
} catch {
    Write-SetupLog "Failed to disable Last Access Timestamp: $_"
}

# 5. Disable App Launch Tracking
Set-RegistryKey -Path "HKLM\SOFTWARE\Policies\Microsoft\Windows\EdgeUI" -Name "DisableMFUTracking" -Value 1 -Type DWord
Set-RegistryKey -Path "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" -Name "NoInstrumentation" -Value 1 -Type DWord

Write-SetupLog "System Optimizations Applied."

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

$scripts = @(
    "$PSScriptRoot\Drivers\Install-Network.ps1",
    "$PSScriptRoot\Tweaks\Remove-Bloatware.ps1",
    "$PSScriptRoot\Tweaks\Configure-Privacy.ps1",
    "$PSScriptRoot\Tweaks\Optimize-System.ps1",
    "$PSScriptRoot\Drivers\Install-Nvidia.ps1",
    "$PSScriptRoot\Drivers\Install-AMD.ps1",
    "$PSScriptRoot\Drivers\Install-Focusrite.ps1",
    "$PSScriptRoot\Apps\Install-Runtimes.ps1",
    "$PSScriptRoot\Apps\Install-Chrome.ps1",
    "$PSScriptRoot\Tweaks\SetStartPins.ps1"
)

Write-SetupLog "Starting Specialize Pass (Optimized)..."

foreach ($script in $scripts) {
    if (Test-Path $script) {
        Write-SetupLog "Executing $script..."
        try {
            & $script
        } catch {
            Write-SetupLog "Error executing $($script): $_"
        }
    } else {
        Write-SetupLog "Script not found: $script"
    }
}

# Generate SetupComplete.cmd for post-OOBE cleanup
# This ensures unattend.xml is removed to prevent sensitive data leak (if any)
# We do NOT remove the Scripts folder here because UserOnce.ps1 (RunOnce) needs it.
$setupCompleteContent = @"
del /q /f "%WINDIR%\Panther\unattend.xml"
del /q /f "%WINDIR%\Panther\unattend-original.xml"
"@

$setupCompletePath = "$env:SystemRoot\Setup\Scripts\SetupComplete.cmd"
try {
    $setupDir = Split-Path -Path $setupCompletePath -Parent
    if (-not (Test-Path $setupDir)) {
        New-Item -Path $setupDir -ItemType Directory -Force | Out-Null
    }
    Set-Content -Path $setupCompletePath -Value $setupCompleteContent -Force
    Write-SetupLog "Generated SetupComplete.cmd for cleanup."
} catch {
    Write-SetupLog "Error creating SetupComplete.cmd: $_"
}

Write-SetupLog "Specialize Pass Completed."

$ErrorActionPreference = 'Stop'
. "$PSScriptRoot\Lib\Helper.ps1"

Write-SetupLog "Configuring User Account..."

# Register Daily Winget Auto-Update Task (Transparent)
if (Get-Command winget -ErrorAction SilentlyContinue) {
    $taskName = "DailySoftwareUpdate"
    $wingetCmd = "winget source update; winget upgrade --all --include-unknown --silent --disable-interactivity --accept-source-agreements --accept-package-agreements"
    $action = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-WindowStyle Hidden -Command `"$wingetCmd`""
    $trigger = New-ScheduledTaskTrigger -Daily -At 13:00
    # Attempt 1: Try with Highest RunLevel (Admin)
    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -Hidden -RunOnlyIfNetworkAvailable

    $registered = $false
    try {
        Write-SetupLog "Attempting to register Winget task with Highest privileges..."
        Register-ScheduledTask -Action $action -Trigger $trigger -Settings $settings -TaskName $taskName -Description "Automatically updates all software via Winget silently." -RunLevel Highest -Force -ErrorAction Stop | Out-Null
        $registered = $true
        Write-SetupLog "Registered Daily Winget Auto-Update Task (Highest)."
    } catch {
        Write-SetupLog "Failed to register Winget task with Highest privileges: $_"
    }

    # Attempt 2: Try with Limited (User) privileges if Admin failed (e.g., UAC issue)
    if (-not $registered) {
        try {
            Write-SetupLog "Attempting to register Winget task with Limited privileges..."
            Register-ScheduledTask -Action $action -Trigger $trigger -Settings $settings -TaskName $taskName -Description "Automatically updates all software via Winget silently." -RunLevel Limited -Force -ErrorAction Stop | Out-Null
            $registered = $true
            Write-SetupLog "Registered Daily Winget Auto-Update Task (Limited)."
        } catch {
            Write-SetupLog "Failed to register Winget task (Limited): $_"
        }
    }
} else {
    Write-SetupLog "Winget not found. Skipping auto-update task registration."
}

Write-SetupLog "User Configuration Completed."

# Self-Destruct: Cleanup Scripts
# Wait 5 seconds then delete the script folder
Start-Process -FilePath "powershell.exe" -ArgumentList "-WindowStyle Hidden -Command `"Start-Sleep -Seconds 5; Remove-Item -Path '$env:SystemRoot\Setup\Scripts' -Recurse -Force`"" -WindowStyle Hidden
